"""A join between two library clips made by ARDY (nv-tlabs/ardy, no text; docs/OWNED_SCENE_PLAN.md, "ARDY joins"): the last three
frames of A and the first three of B (turned TURN degrees about the vertical, B's place where its clip has it) are fixed, ARDY fills
FRAMES in all on mini4 (authoring/render/ardy-gen.py, ~/Yun/ardy-runner), the calmest of the samples is mapped onto the Studio
skeleton in Blender (authoring/render/ardy-blender.py) and registered as move-ardy-NAME. perform.py's go/rise take it as `join`
(played from A's last frame to B's first). Clips are the Studio GLBs mixamo-retarget.py wrote; files in .authoring/sources/ardy/.
  python3 authoring/render/ardy-join.py NAME A.glb:LAST B.glb TURN FRAMES [--samples 8] [--seed 1] [--model ardy|kimodo] [--text 'A person ...'] [--path FROM,TO] [--steps Rs0-8,Re18-39,...]   (Kimodo only; --path holds the hips on the line between the key poses and turns their heading over that part of the gap, 0,1 the whole; --steps holds a foot (L|R) where the start (s) or end (e) poses have it, or raised 12 cm halfway (l) over those frames; --text encoded on mini4 by Llama-3-8B and cached; LAST: A's last frame played, -1 its end; Kimodo: the whole clip at once, real steps, about 2.5 minutes a sample on mini4)"""
import sys,os,json,subprocess
argv=sys.argv[1:];name,a,b,turn,frames=argv[0],argv[1],argv[2],float(argv[3]),int(argv[4]);opt=lambda k,d:type(d)(argv[argv.index(k)+1]) if k in argv else d
root=os.path.abspath(os.path.join(os.path.dirname(__file__),'../..'));D=os.path.join(root,'.authoring/sources/ardy');os.makedirs(D+'/json',exist_ok=True);os.makedirs(D+'/studio',exist_ok=True)
BL='/Applications/Blender.app/Contents/MacOS/Blender';HOST,RUN='tim@mini4.local','Yun/ardy-runner'
ap,af=a.rsplit(':',1);af=int(af);first=[f'{ap}:{af-2}',f'{ap}:{af-1}',f'{ap}:{af}'] if af>=0 else [f'{ap}:{af-2}',f'{ap}:{af-1}',f'{ap}:{af}']
poses=f'{D}/json/{name}.poses.json';subprocess.run([BL,'-b','-P',os.path.join(root,'authoring/render/ardy-blender.py'),'--','poses',poses,*first,f'{b}:0',f'{b}:1',f'{b}:2'],check=True,capture_output=True)
P=json.load(open(poses));req=f'{D}/json/{name}.request.json';json.dump(dict(frames=frames,start=P['poses'][:3],end=P['poses'][3:],turn=turn,leg=P['leg'],seed=opt('--seed',1),samples=opt('--samples',8),**({'text':opt('--text','')} if opt('--text','') else {}),**({'stepPlan':[dict(foot=x[0],at={'s':'start','e':'end','l':'lift'}[x[1]],frames=[int(v) for v in x[2:].split('-')]) for x in opt('--steps','').split(',')]} if opt('--steps','') else {}),**({'path':{'turn':[float(x) for x in opt('--path','').split(',')]}} if opt('--path','') else {})),open(req,'w'))
subprocess.run(['scp','-q',os.path.join(root,'authoring/render/ardy-gen.py'),os.path.join(root,'authoring/render/kimodo-gen.py'),req,f'{HOST}:{RUN}/'],check=True)
gen,py=('kimodo-gen.py','kimodo-venv/bin/python') if opt('--model','ardy')=='kimodo' else ('ardy-gen.py','.venv/bin/python')
r=subprocess.run(['ssh',HOST,f'cd ~/{RUN} && {py} {gen} {os.path.basename(req)} {name}.out.json 2>/dev/null | tail -1'],check=True,capture_output=True,text=True).stdout.strip();print(r)
out=f'{D}/json/{name}.out.json';subprocess.run(['scp','-q',f'{HOST}:{RUN}/{name}.out.json',out],check=True)
O=json.load(open(out));s=O['samples'][O['best']];mo=f'{D}/json/{name}.motion.json';json.dump(dict(joints=O['joints'],G=s['G'],hips=s['hips'],ankles=s.get('ankles'),scale=O['scale']),open(mo,'w'))
tmp=f'{D}/studio-{name}';os.makedirs(tmp,exist_ok=True);glb=f'{tmp}/{name}.glb'
subprocess.run([BL,'-b','-P',os.path.join(root,'authoring/render/ardy-blender.py'),'--','retarget',os.path.join(root,'editor/assets/character.glb'),mo,glb],check=True,capture_output=True)
src=f'{"Kimodo (nv-tlabs/kimodo" if opt("--model","ardy")=="kimodo" else "ARDY (nv-tlabs/ardy"}, SOMA, {repr(opt("--text","")) if opt("--text","") else "no text"}) between {os.path.basename(ap)} and {os.path.basename(b)}'
print(subprocess.run(['python3',os.path.join(root,'authoring/render/mixamo-register.py'),tmp,'--source',src,'--prefix','move-ardy-','--notes',f'ARDY join: the last three frames of {os.path.basename(ap)} (to frame {af}) and the first three of {os.path.basename(b)} turned {turn:g} degrees fixed, {frames} frames, sample {O["best"]} of {len(O["samples"])} (the calmest), seed {opt("--seed",1)}; SOMA rotations mapped by world turn from the shared T-pose, hips scaled by leg length (authoring/render/ardy-join.py).'],check=True,capture_output=True,text=True).stdout.replace('\n',''))
